def has_close_elements(numbers: List[float], threshold: float) -> bool:
    """
    Returns True if any two numbers in the list are closer to each other than the given threshold.
    """
    if len(numbers) < 2:
        return False
    nums_sorted = sorted(numbers)
    for i in range(1, len(nums_sorted)):
        if abs(nums_sorted[i] - nums_sorted[i - 1]) < threshold:
            return True
    return False

