def separate_paren_groups(paren_string: str) -> List[str]:
    cleaned = paren_string.replace(' ', '')
    groups = []
    depth = 0
    start = 0
    for i, ch in enumerate(cleaned):
        if ch == '(':
            if depth == 0:
                start = i
            depth += 1
        elif ch == ')':
            depth -= 1
            if depth == 0:
                groups.append(cleaned[start:i + 1])
    return groups

