def max_value_on_paths(N, grid_values):
    """
    Calculate the maximum sum of values collected on two paths in an N x N grid.
    """
    # Construct the grid (1-indexed)
    grid = [[0] * (N + 1) for _ in range(N + 1)]
    for x, y, val in grid_values:
        if x == 0 and y == 0 and val == 0:
            break
        grid[x][y] = val

    if N == 0:
        return 0

    # dp_prev[x1][x2] = maximum sum at step k-1 for paths ending at (x1, y1) and (x2, y2)
    dp_prev = [[float('-inf')] * (N + 1) for _ in range(N + 1)]
    dp_prev[1][1] = grid[1][1]

    # Iterate over all steps k = x + y, from 3 to 2N
    for k in range(3, 2 * N + 1):
        dp_curr = [[float('-inf')] * (N + 1) for _ in range(N + 1)]
        min_x = max(1, k - N)
        max_x = min(N, k - 1)
        for x1 in range(min_x, max_x + 1):
            y1 = k - x1
            if y1 < 1 or y1 > N:
                continue
            for x2 in range(min_x, max_x + 1):
                y2 = k - x2
                if y2 < 1 or y2 > N:
                    continue

                best = float('-inf')
                for prev_x1 in (x1 - 1, x1):
                    if prev_x1 < 1 or prev_x1 > N:
                        continue
                    prev_y1 = (k - 1) - prev_x1
                    if prev_y1 < 1 or prev_y1 > N:
                        continue
                    for prev_x2 in (x2 - 1, x2):
                        if prev_x2 < 1 or prev_x2 > N:
                            continue
                        prev_y2 = (k - 1) - prev_x2
                        if prev_y2 < 1 or prev_y2 > N:
                            continue
                        prev_val = dp_prev[prev_x1][prev_x2]
                        if prev_val == float('-inf'):
                            continue
                        add = grid[x1][y1]
                        if x1 != x2 or y1 != y2:
                            add += grid[x2][y2]
                        cand = prev_val + add
                        if cand > best:
                            best = cand
                dp_curr[x1][x2] = best
        dp_prev = dp_curr

    result = dp_prev[N][N]
    return int(result) if result != float('-inf') else 0

