def max_value_on_paths(N: int, grid_values: list) -> int:
    # Build the grid with 1-based indexing
    grid = [[0] * (N + 1) for _ in range(N + 1)]
    for x, y, val in grid_values:
        if x == 0 and y == 0 and val == 0:
            break
        if 1 <= x <= N and 1 <= y <= N:
            grid[x][y] = val

    if N == 1:
        return grid[1][1]

    # dp[x1][x2] = maximum sum when both walkers are at positions
    # (x1, y1) and (x2, y2) after the same number of steps.
    neg_inf = -10**9
    dp = [[neg_inf] * (N + 1) for _ in range(N + 1)]
    dp[1][1] = grid[1][1]  # start position

    # step = x + y, starting from 3 because (1,1) already handled
    for step in range(3, 2 * N + 1):
        new_dp = [[neg_inf] * (N + 1) for _ in range(N + 1)]
        # x1 and x2 must satisfy 1 <= x <= N and 1 <= y <= N
        for x1 in range(max(1, step - N), min(N, step - 1) + 1):
            y1 = step - x1
            if y1 < 1 or y1 > N:
                continue
            for x2 in range(max(1, step - N), min(N, step - 1) + 1):
                y2 = step - x2
                if y2 < 1 or y2 > N:
                    continue
                best = neg_inf
                # Consider the four possible previous moves for each walker
                for prev_dx1 in (0, 1):  # 0 = came from down, 1 = came from right
                    prev_x1 = x1 - prev_dx1
                    prev_y1 = y1 - (1 - prev_dx1)
                    if prev_x1 < 1 or prev_y1 < 1:
                        continue
                    for prev_dx2 in (0, 1):
                        prev_x2 = x2 - prev_dx2
                        prev_y2 = y2 - (1 - prev_dx2)
                        if prev_x2 < 1 or prev_y2 < 1:
                            continue
                        val = dp[prev_x1][prev_x2]
                        if val > best:
                            best = val
                if best == neg_inf:
                    continue
                add = grid[x1][y1]
                if x1 != x2 or y1 != y2:
                    add += grid[x2][y2]
                new_dp[x1][x2] = best + add
        dp = new_dp

    return dp[N][N]

