def find_number_combinations():
    from itertools import permutations
    results = []
    digits = '123456789'
    # Generate all possible first numbers from length 1 to 9
    for length in range(1, 10):
        for perm in permutations(digits, length):
            first = int(''.join(perm))
            second = first * 2
            third = first * 3
            # Function to check if a number uses only digits 1-9 without repetition
            def valid(num):
                s = str(num)
                if '0' in s:
                    return False
                return len(set(s)) == len(s)
            if valid(second) and valid(third):
                results.append((first, second, third))
    # Remove duplicate combinations where same first leads to same pair (since permutations may repeat first from different digit order)
    unique_results = {}
    for combo in results:
        unique_results[combo[0]] = combo  # keep one entry per first number
    sorted_results = sorted(unique_results.values(), key=lambda x: x[0])
    return sorted_results

