def max_product(num_str: str, N: int, K: int) -> int:
    """Return the maximum product obtainable by inserting K multiplication signs
    into the numeric string `num_str` of length `N`.  The string is split into
    K+1 contiguous parts and each part is interpreted as an integer.  If a
    valid split is impossible, the function returns 0."""
    if K == 0:
        return int(num_str)

    # dp[i][k] = maximum product for the prefix num_str[:i] with k cuts
    dp = [[None] * (K + 1) for _ in range(N + 1)]

    # Base case: 0 cuts
    dp[0][0] = 1  # dummy value for transitions
    for i in range(1, N + 1):
        dp[i][0] = int(num_str[:i])

    # Fill DP table
    for k in range(1, K + 1):
        # The shortest prefix that can have k cuts has length k
        for i in range(k, N + 1):
            best = None
            # Consider the last part that ends at position i
            for j in range(k, i):
                prev = dp[j][k - 1]
                if prev is None:
                    continue
                part_val = int(num_str[j:i])
                prod_val = prev * part_val
                if best is None or prod_val > best:
                    best = prod_val
            dp[i][k] = best

    result = dp[N][K]
    return result if result is not None else 0

