def optimize_seating(M: int, N: int, K: int, L: int, D: int, chatting_pairs: list) -> (str, str):
    from itertools import combinations

    # Build horizontal and vertical aisle lists
    horizontal_positions = list(range(1, M))  # aisles between row i and i+1
    vertical_positions = list(range(1, N))    # aisles between col j and j+1

    # Map each aisle to the set of pair indices it separates
    hor_sets = {i: set() for i in horizontal_positions}
    ver_sets = {j: set() for j in vertical_positions}

    for idx, (x1, y1, x2, y2) in enumerate(chatting_pairs):
        r_min, r_max = min(x1, x2), max(x1, x2)
        c_min, c_max = min(y1, y2), max(y1, y2)

        # Horizontal aisles
        for i in range(r_min, r_max):
            hor_sets[i].add(idx)

        # Vertical aisles
        for j in range(c_min, c_max):
            ver_sets[j].add(idx)

    best_separated = -1
    best_rows = []
    best_cols = []

    # If no rows to choose, relax combination to single empty set
    row_combinations = [()] if K == 0 else list(combinations(horizontal_positions, K))
    col_combinations = [()] if L == 0 else list(combinations(vertical_positions, L))

    for rows_choice in row_combinations:
        # Union of horizontal sets
        if rows_choice:
            hor_union = set().union(*(hor_sets[i] for i in rows_choice))
        else:
            hor_union = set()

        for cols_choice in col_combinations:
            if cols_choice:
                ver_union = set().union(*(ver_sets[j] for j in cols_choice))
            else:
                ver_union = set()

            total_separated = len(hor_union | ver_union)

            if total_separated > best_separated:
                best_separated = total_separated
                best_rows = list(rows_choice)
                best_cols = list(cols_choice)
            elif total_separated == best_separated:
                # Tie-breaking: choose lexicographically smaller rows, then columns
                if list(rows_choice) < best_rows or (list(rows_choice) == best_rows and list(cols_choice) < best_cols):
                    best_rows = list(rows_choice)
                    best_cols = list(cols_choice)

    row_str = ' '.join(str(r) for r in sorted(best_rows))
    col_str = ' '.join(str(c) for c in sorted(best_cols))
    return (row_str, col_str)

