def count_partitions(n: int, k: int, x: int) -> int:
    # Remaining value after giving each part the minimum x
    remaining = n - k * x
    if remaining < 0:
        return 0
    if k <= 0:
        return 1 if remaining == 0 else 0

    # dp[i][j] = number of partitions of i using parts with maximum size j
    dp = [[0] * (k + 1) for _ in range(remaining + 1)]
    for j in range(k + 1):
        dp[0][j] = 1  # one partition of zero: the empty partition

    for i in range(1, remaining + 1):
        for j in range(1, k + 1):
            if i >= j:
                dp[i][j] = dp[i][j-1] + dp[i-j][j]
            else:
                dp[i][j] = dp[i][j-1]

    return dp[remaining][k]

