def count_sequences(n: int, last: int, memo: dict) -> int:
    if last in memo:
        return memo[last]
    if last <= 1:
        memo[last] = 1
        return 1
    total = 1
    max_next = last // 2
    for k in range(1, max_next + 1):
        total += count_sequences(n, k, memo)
    memo[last] = total
    return total

