def preorder_traversal(inorder: str, postorder: str) -> str:
    if not inorder:
        return ""
    # Map each character to its position in inorder for quick lookup
    idx_map = {c: i for i, c in enumerate(inorder)}

    def build(in_left: int, in_right: int, post_left: int, post_right: int) -> str:
        if in_left > in_right:
            return ""
        # Root is the last element in the current postorder subarray
        root = postorder[post_right]
        root_idx = idx_map[root]
        # Number of nodes in the left subtree
        left_size = root_idx - in_left
        # Recursively build left and right subtrees
        left_pre = build(in_left, root_idx - 1, post_left, post_left + left_size - 1)
        right_pre = build(root_idx + 1, in_right, post_left + left_size, post_right - 1)
        return root + left_pre + right_pre

    return build(0, len(inorder) - 1, 0, len(postorder) - 1)

