def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    import re

    # Normalize names to uppercase for comparison
    scenario = scenario.upper()
    liar_set = {name.upper() for name in liar_count}
    days_set = {day.upper() for day in days_of_week}

    # Helper to determine if a statement references a day (ignore such statements)
    def contains_day(text: str) -> bool:
        for day in days_set:
            if re.search(r'\b' + re.escape(day) + r'\b', text, re.IGNORECASE):
                return True
        return False

    # Helper to parse guilt related statements
    def parse_guilt(text: str, speaker: str):
        """
        Returns (subject, is_guilty) if the statement is about guilt.
        subject is the name of the person being referred to.
        is_guilty is True if the statement says the person is guilty, False if says not guilty.
        If the statement cannot be parsed, returns (None, None).
        """
        patterns = [
            # I am guilty
            (r'I\s+am\s+guilty\.?', speaker, True),
            # I am not guilty
            (r'I\s+am\s+not\s+guilty\.?', speaker, False),
            # X is guilty
            (r'(?P<person>[A-Z]+)\s+is\s+guilty\.?', None, True),
            # X is not guilty
            (r'(?P<person>[A-Z]+)\s+is\s+not\s+guilty\.?', None, False),
        ]
        for pattern, default_subject, guilty_val in patterns:
            match = re.match(pattern, text, re.IGNORECASE)
            if match:
                if default_subject is not None:
                    subject = default_subject
                else:
                    subject = match.group('person')
                return subject.upper(), guilty_val
        return None, None

    # Process each participant's statements
    for speaker, stmt_list in statements.items():
        speaker = speaker.upper()
        for stmt in stmt_list:
            # ignore empty strings
            if not stmt.strip():
                continue
            # ignore statements about day of week
            if contains_day(stmt):
                continue
            subject, said_guilt = parse_guilt(stmt, speaker)
            if subject is None:
                # Statement does not mention guilt or is unparseable; ignore
                continue
            # Evaluate the truth of the statement based on the scenario
            actual_guilt = (subject == scenario)
            truth_value = (actual_guilt == said_guilt)
            # If speaker is a liar, the statement must be false; otherwise it must be true
            if speaker in liar_set:
                if truth_value:
                    return False  # liar made a true statement -> inconsistency
            else:
                if not truth_value:
                    return False  # truth teller made a false statement -> inconsistency
    return True

