def calculate_arrangements(n, m, a) -> int:
    MOD = 10**6 + 7
    if m < 0:
        return 0
    total_available = sum(a)
    if m > total_available:
        return 0

    dp_prev = [0] * (m + 1)
    dp_prev[0] = 1

    for limit in a:
        prefix = [0] * (m + 1)
        prefix[0] = dp_prev[0]
        for i in range(1, m + 1):
            prefix[i] = (prefix[i - 1] + dp_prev[i]) % MOD
        dp_cur = [0] * (m + 1)
        for k in range(m + 1):
            if k <= limit:
                dp_cur[k] = prefix[k] % MOD
            else:
                dp_cur[k] = (prefix[k] - prefix[k - limit - 1]) % MOD
        dp_prev = dp_cur

    return dp_prev[m] % MOD

