def minimum_students_to_leave(heights):
    """
    Calculate the minimum number of students that need to leave to form a choir formation,
    where the heights increase up to a peak and then decrease.

    :param heights: List[int] - heights of students
    :return: int - minimum number of students that need to leave
    """
    n = len(heights)
    if n == 0:
        return 0

    # Longest increasing subsequence ending at each position
    lis = [1] * n
    for i in range(n):
        for j in range(i):
            if heights[j] < heights[i] and lis[j] + 1 > lis[i]:
                lis[i] = lis[j] + 1

    # Longest decreasing subsequence starting at each position
    lds = [1] * n
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if heights[j] < heights[i] and lds[j] + 1 > lds[i]:
                lds[i] = lds[j] + 1

    # Maximize total length of increase + decrease - 1 (peak counted twice)
    longest_bitonic = 0
    for i in range(n):
        bitonic_len = lis[i] + lds[i] - 1
        if bitonic_len > longest_bitonic:
            longest_bitonic = bitonic_len

    # Minimum removals
    return n - longest_bitonic

